requests.query:
query Gql {
  viewer {
    email
    name
  }
}

query Gql($v0: Int, $v1: Boolean, $v2: Int) {
  teams(first: $v0, includeArchived: $v1) {
    edges {
      node {
        id
        key
        members(first: $v2) {
          edges {
            node {
              name
            }
          }
        }
      }
    }
  }
}

query Gql($v0: String!, $v1: String!) {
  issue(id: $v0) {
    title
    assignee {
      email
    }
  }
  issue_0: issue(id: $v1) {
    title
  }
}

query Gql($v0: String!, $v1: Boolean) {
  team(id: $v0) {
    issueCount(includeArchived: $v1)
    issueCount_0: issueCount
  }
}

query Gql($v0: Int) {
  teams(first: $v0) {
    edges {
      node {
        private
        name
      }
    }
  }
}

mutation Gql($v0: IssueCreateInput!) {
  issueCreate(input: $v0) {
    issue {
      identifier
    }
  }
}

query Gql($v0: Int) {
  teams(first: $v0) {
    edges {
      node {
        id
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query Gql($v0: Int, $v1: String) {
  teams(first: $v0, after: $v1) {
    edges {
      node {
        id
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query Gql {
  viewer {
    id
  }
}

query Gql($v0: String!, $v1: Int) {
  project(id: $v0) {
    name
    services(first: $v1) {
      edges {
        node {
          name
        }
      }
    }
  }
}

mutation Gql($v0: VariableCollectionUpsertInput!, $v1: VariableCollectionUpsertInput!) {
  variableCollectionUpsert(input: $v0)
  variableCollectionUpsert_0: variableCollectionUpsert(input: $v1)
}

mutation Gql($v0: ApiTokenCreateInput!) {
  apiTokenCreate(input: $v0)
}

query Gql($v0: String!, $v1: String!, $v2: String!) {
  bucketS3Credentials(bucketId: $v0, environmentId: $v1, projectId: $v2) {
    accessKeyId
    secretAccessKey
  }
}

query Gql($v0: String!, $v1: Int) {
  project(id: $v0) {
    services(first: $v1) {
      edges {
        node {
          name
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
}

query Gql($v0: String!, $v1: Int, $v2: String) {
  project(id: $v0) {
    services(first: $v1, after: $v2) {
      edges {
        node {
          name
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
}

query Gql($v0: String!, $v1: AppProfileImageWidth) {
  app {
    byId(appId: $v0) {
      profileImageUrl(width: $v1)
      fullName
    }
  }
}

query Gql {
  viewer {
    username
  }
}

query Gql($v0: String!, $v1: String!, $v2: Int, $v3: [IssueState!], $v4: Int!) {
  repository(name: $v0, owner: $v1) {
    issues(first: $v2, states: $v3) {
      edges {
        node {
          number
          title
        }
      }
    }
    pullRequest(number: $v4) {
      title
    }
  }
}

mutation Gql($v0: ConvertPullRequestToDraftInput!) {
  convertPullRequestToDraft(input: $v0) {
    pullRequest {
      isDraft
    }
  }
}

query Gql($v0: Int, $v1: String!, $v2: SearchType!) {
  search(first: $v0, query: $v1, type: $v2) {
    edges {
      node {
        __typename
      }
    }
  }
}

query Gql($v0: Int) {
  viewer {
    avatarUrl(size: $v0)
    avatarUrl_0: avatarUrl
    login
  }
}

query Gql($v0: Int, $v1: Boolean) {
  apps(first: $v0, active: $v1) {
    edges {
      node {
        name
        organization {
          slug
        }
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query Gql($v0: Int, $v1: Boolean, $v2: String) {
  apps(first: $v0, active: $v1, after: $v2) {
    edges {
      node {
        name
        organization {
          slug
        }
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query Gql($v0: String) {
  addOn(name: $v0) {
    environment
    password
  }
}

query Gql($v0: String, $v1: String!) {
  organization(slug: $v0) {
    agreedToProviderTos(providerName: $v1)
  }
}
